def test_known_probs():
    p = solution.epsilon_greedy_probs([2.8, 1.5, 1.0, 0.2], 0.2)
    assert abs(p[0] - 0.85) < 1e-12
    assert abs(p[1] - 0.05) < 1e-12

def test_sums_to_one():
    p = solution.epsilon_greedy_probs([1.0, 2.0, 3.0], 0.3)
    assert abs(sum(p) - 1.0) < 1e-12

def test_pure_greedy():
    assert solution.epsilon_greedy_probs([1.0, 5.0, 3.0], 0.0) == [0.0, 1.0, 0.0]

def test_pure_random():
    p = solution.epsilon_greedy_probs([1.0, 2.0, 3.0, 4.0], 1.0)
    assert all(abs(x - 0.25) < 1e-12 for x in p)

def test_ties_split():
    p = solution.epsilon_greedy_probs([1.0, 1.0, 0.0], 0.2)
    assert abs(p[0] - p[1]) < 1e-12
    assert abs(p[0] - (0.4 + 0.2 / 3)) < 1e-12
    assert abs(p[2] - 0.2 / 3) < 1e-12

def test_invalid_epsilon():
    try:
        solution.epsilon_greedy_probs([1.0, 2.0], 1.5)
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_empty():
    try:
        solution.epsilon_greedy_probs([], 0.1)
    except ValueError:
        return
    raise AssertionError("expected ValueError")
